vec3 hacher32(vec2 position) {
    vec3 position3d = fract(vec3(position.xyx) * vec3(0.1031, 0.1030, 0.0973));
    position3d += dot(position3d, position3d.yxz + 33.33);
    return fract((position3d.xxy + position3d.yzz) * position3d.zyx);
}

float distanceBoite2D(vec2 position, vec2 demiDimensions) {
    vec2 ecart = abs(position) - demiDimensions;
    float distanceExterieure = length(max(ecart, 0.0));
    float distanceInterieure = min(max(ecart.x, ecart.y), 0.0);
    return distanceExterieure + distanceInterieure;
}

vec3 ajustementTonaleACES(vec3 couleurLDR) {
    float coefficientA = 2.51;
    float coefficientB = 0.03;
    float coefficientC = 2.43;
    float coefficientD = 0.59;
    float coefficientE = 0.14;

    vec3 numerateur = couleurLDR * (coefficientA * couleurLDR + coefficientB);
    vec3 denominateur = couleurLDR * (coefficientC * couleurLDR + coefficientD) + coefficientE;

    return clamp(numerateur / denominateur, 0.0, 1.0);
}

void mainImage(out vec4 couleurFragment, in vec2 coordFragment)
{
    vec2 coordonneesNormalisees = coordFragment / iResolution.xy;
    vec2 positionEspaceGlobal = coordonneesNormalisees * 400.0;

    float tempsSecondesBase = (float(iFrame) + 1.0) / 30.0;

    vec2 centreGrilleActuelle = floor((positionEspaceGlobal - 10.0) / 20.0) * 20.0 + 10.0;

    vec3 couleurFinale = texture(iChannel0, coordonneesNormalisees).rgb;
    float taillePixelEspaceGlobal = 99.0 / min(iResolution.x, iResolution.y);

    const int NOMBRE_ECHANTILLONS_MB = 32;
    float dureeObturateur = 0.25;

    vec3 couleurAccumuleeCubes = vec3(0.0);
    float alphaAccumuleCubes = 0.0;

    for (int echantillon = 0; echantillon < NOMBRE_ECHANTILLONS_MB; echantillon++) {
        float decalageTemps = (float(echantillon) / float(NOMBRE_ECHANTILLONS_MB - 1) - 0.5) * dureeObturateur;
        float tempsEchantillon = tempsSecondesBase + decalageTemps;

        float distanceMinimale = 1e5;
        vec3 couleurCubeSelectionne = vec3(0.0);
        vec2 decalageCentreCube = vec2(0.0);

        for (int decalageX = -2; decalageX <= 2; decalageX++) {
            for (int decalageY = -2; decalageY <= 2; decalageY++) {
                vec2 positionCellule = centreGrilleActuelle + vec2(float(decalageX), float(decalageY)) * 20.0;

                bool horsLimitesX = positionCellule.x < 0.0 || positionCellule.x >= 400.0;
                bool horsLimitesY = positionCellule.y < 0.0 || positionCellule.y >= 400.0;
                if (horsLimitesX || horsLimitesY) {
                    continue;
                }

                float angleRotation = atan(positionCellule.y - 200.0, positionCellule.x - 200.0) + tempsEchantillon;
                vec2 positionRelativeOrbital = positionCellule + 20.0 * vec2(cos(angleRotation), sin(angleRotation));
                vec2 centreBoite = positionRelativeOrbital + vec2(5.0);

                float distanceCourante = distanceBoite2D(positionEspaceGlobal - centreBoite, vec2(5.0));

                if (distanceCourante < distanceMinimale) {
                    distanceMinimale = distanceCourante;
                    decalageCentreCube = positionEspaceGlobal - centreBoite;

                    vec3 valeurAleatoire = hacher32(positionCellule);
                    vec3 couleurNormalisee = vec3(
                        valeurAleatoire.x * 400.0,
                        valeurAleatoire.y * 200.0,
                        valeurAleatoire.z * 200.0
                    ) / 255.0;

                    couleurCubeSelectionne = min(couleurNormalisee, vec3(1.0));
                }
            }
        }

        float facteurAlpha = 1.0 - smoothstep(-taillePixelEspaceGlobal, taillePixelEspaceGlobal, distanceMinimale);

        if (facteurAlpha > 0.0) {
            vec3 normaleSurface = normalize(vec3(decalageCentreCube / 5.0, 0.8));
            vec3 directionLumiere = normalize(vec3(0.5, 0.7, 1.0));
            vec3 directionVue = vec3(0.0, 0.0, 1.0);
            vec3 demiVecteurLumiereVue = normalize(directionLumiere + directionVue);

            float intensiteDiffuse = max(dot(normaleSurface, directionLumiere), 0.15);
            float intensiteSpeculaire = pow(max(dot(normaleSurface, demiVecteurLumiereVue), 0.0), 32.0) * 0.6;
            float occlusionAmbiante = smoothstep(5.0, 0.0, length(decalageCentreCube));

            vec3 couleurEclairee = couleurCubeSelectionne * intensiteDiffuse + vec3(intensiteSpeculaire) + (occlusionAmbiante * 0.1);

            couleurAccumuleeCubes += couleurEclairee * facteurAlpha;
            alphaAccumuleCubes += facteurAlpha;
        }
    }

    if (alphaAccumuleCubes > 0.0) {
        vec3 couleurMoyenneCubes = couleurAccumuleeCubes / float(NOMBRE_ECHANTILLONS_MB);
        float alphaMoyenCubes = alphaAccumuleCubes / float(NOMBRE_ECHANTILLONS_MB);
        couleurFinale = mix(couleurFinale, couleurMoyenneCubes / alphaMoyenCubes, alphaMoyenCubes);
    }

    vec2 decalageAberrationChromatique = (coordonneesNormalisees - 0.5) * 0.005;

    vec2 coordonneesCanalRouge = coordonneesNormalisees + decalageAberrationChromatique;
    float composanteRougeTexture = texture(iChannel0, coordonneesCanalRouge).r;
    couleurFinale.r = mix(couleurFinale.r, composanteRougeTexture, 0.15);

    vec2 coordonneesCanalBleu = coordonneesNormalisees - decalageAberrationChromatique;
    float composanteBleuTexture = texture(iChannel0, coordonneesCanalBleu).b;
    couleurFinale.b = mix(couleurFinale.b, composanteBleuTexture, 0.15);

    couleurFinale = ajustementTonaleACES(couleurFinale);
    couleurFinale = pow(couleurFinale, vec3(1.0 / 2.2));

    float facteurVignettage = coordonneesNormalisees.x * coordonneesNormalisees.y * (1.0 - coordonneesNormalisees.x) * (1.0 - coordonneesNormalisees.y);
    facteurVignettage = clamp(pow(16.0 * facteurVignettage, 0.25), 0.0, 1.0);
    couleurFinale *= facteurVignettage;

    couleurFragment = vec4(couleurFinale, 1.0);
}
